"use strict"

module.exports.defaultChar = "?"

module.exports.encode = function encode (str, encoding) {
  str = "" + (str || "")
  var codec = module.exports.getCodec(encoding)
  return codec.name + ":" + str + module.exports.defaultChar
}

module.exports.getCodec = function getCodec (encoding) {
  var enc = module.exports._canonicalize(encoding)
  return { name: enc }
}

module.exports._canonicalize = function (encoding) {
  return ("" + encoding).toLowerCase().replace(/[^0-9a-z]/g, "")
}

module.exports.toEncoding = module.exports.encode
